const input = $input.first().json;
const headers = input.headers || {};
const body = (typeof input.body === "object" && input.body !== null) ? input.body : {};

function getHeader(h, key) {
  const k = key.toLowerCase();
  for (const [n, v] of Object.entries(h)) {
    if (n.toLowerCase() === k) return Array.isArray(v) ? v[0] : v;
  }
}

const event = getHeader(headers, "x-blacklabel-event");
const ts    = getHeader(headers, "x-blacklabel-timestamp");
const sig   = getHeader(headers, "x-blacklabel-signature");

if (event !== "contact_form.submitted") return [{ json: { ok: false, error: "Evento invalido: " + (event || "missing") } }];
if (!ts)  return [{ json: { ok: false, error: "Falta x-blacklabel-timestamp" } }];
if (!sig || !sig.startsWith("sha256=")) return [{ json: { ok: false, error: "Falta x-blacklabel-signature" } }];

// Ventana de frescura anti-replay (mismo patron que WF1): rechaza timestamps fuera de +/-5 min.
const tsMs = Date.parse(ts);
if (!Number.isFinite(tsMs)) return [{ json: { ok: false, error: "x-blacklabel-timestamp invalido" } }];
const skewMs = Math.abs(Date.now() - tsMs);
const MAX_SKEW_MS = 5 * 60 * 1000;
if (skewMs > MAX_SKEW_MS) return [{ json: { ok: false, error: "timestamp fuera de ventana" } }];

const p = body;
const required = ["name", "email", "subject", "message"];
const missing = required.filter(f => !p[f]);
if (missing.length) return [{ json: { ok: false, error: "Payload incompleto: " + missing.join(", ") } }];

return [{ json: { ok: true, name: p.name, email: p.email, subject: p.subject, message: p.message } }];

const legalFooter = `<div style="margin-top:24px;padding-top:14px;border-top:1px solid #ddd;font-size:11px;color:#777;line-height:1.5">Black Label Market es una marca de <strong>KAZAWEB, S.L.U.</strong> (NIF B42761254), con domicilio en Lugar Rebordelo nº 35, Planta 2, 15930 Boiro, A Coruña. Inscrita en el Registro Mercantil de Santiago de Compostela, Tomo 395, Folio 51, Hoja SC-51053.<br>Puedes solicitar la baja de comunicaciones o ejercer tus derechos de privacidad escribiendo a <a href="mailto:privacidad@blacklabelmarket.es">privacidad@blacklabelmarket.es</a>. Consulta nuestra <a href="https://blacklabelmarket.es/legal/privacidad">Política de Privacidad</a>.</div>`;

const d = $input.first().json;
const MAIL_FROM   = $env.MAIL_FROM   || 'Black Label Market <no-reply@blacklabelmarket.es>';
const ADMIN_EMAIL = 'marketing@blackseriesagency.es';

const subjectLabels = {
  suscripcion: 'Gestión de mi suscripción',
  soporte: 'Soporte técnico',
  editorial: 'Revisión editorial de vehículo',
  facturacion: 'Facturación',
  otro: 'Otro',
};
const subjectLabel = subjectLabels[d.subject] || d.subject;

const messageHtml = String(d.message)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/\n/g, '<br>');

const confirmEmailHtml = `<p>Hola ${d.name},</p>
<p>Hemos recibido tu mensaje. Te respondemos en menos de 24 horas laborables.</p>
<p>Un saludo,<br>Black Label Market</p>`;

const internalEmailHtml = `<h2>Nuevo mensaje de contacto</h2>
<p><strong>Nombre:</strong> ${d.name}</p>
<p><strong>Email:</strong> ${d.email}</p>
<p><strong>Asunto:</strong> ${subjectLabel}</p>
<blockquote style="border-left:3px solid #c9a227;padding-left:12px;margin:16px 0;color:#555">${messageHtml}</blockquote>`;

return [{
  json: {
    ...d,
    confirmEmail: { from: MAIL_FROM, to: [d.email], subject: 'Hemos recibido tu mensaje - Black Label Market', html: confirmEmailHtml + legalFooter },
    internalEmail: { from: MAIL_FROM, to: [ADMIN_EMAIL], subject: `Contacto: ${subjectLabel} — ${d.name}`, html: internalEmailHtml }
  }
}];
